python3 -c "import sys, json
try:
    data = json.load(sys.stdin)
except:
    data = {}
cmd = data.get('tool_input', {}).get('command', '') or data.get('toolCall', {}).get('args', {}).get('CommandLine', '')
protected = ['spendly.db', '.env', 'migrations/']
dangerous = ['rm ', 'rm -', 'unlink ', 'truncate ', 'remove(', 'remove ']
blocked = False
deny_reason = ''
for d in dangerous:
    if d in cmd:
        for p in protected:
            if p in cmd:
                blocked = True
                deny_reason = f'BLOCKED: Cannot run destructive command on protected file: {p}'
                break
        if blocked:
            break
if blocked:
    print(deny_reason, file=sys.stderr)
    print(json.dumps({'allow_tool': False, 'deny_reason': deny_reason}))
else:
    print(json.dumps({'allow_tool': True}))"
